const normalizeKey = (s) => s.toLowerCase().replace(/[^a-z0-9]/g, "");

const PHOTO_MAP = {};
Object.entries(PHOTO_FILES).forEach(([letter, files]) => {
  files.forEach((file) => {
    const base = file.replace(/\.[^.]+$/, "");
    PHOTO_MAP[normalizeKey(base)] = `/flowers/${letter}/${encodeURIComponent(file)}`;
  });
});

